<script setup lang="ts">defineProps<{ values: { enabled: boolean; width: number; reliefRadius: number; depthFromLip: number } }>(); const emit = defineEmits<{ update: [key: 'enabled' | 'width' | 'reliefRadius' | 'depthFromLip', value: number | boolean] }>();</script>
<template><section class="control-group"><div class="row"><h3>Corner flex slits</h3><ToggleSwitch :model-value="values.enabled" @update:model-value="v => emit('update','enabled',Boolean(v))"/></div><template v-if="values.enabled"><label>Slit width <output>{{ values.width.toFixed(1) }} mm</output></label><Slider :model-value="values.width" :min="0.5" :max="4" :step="0.1" @update:model-value="v => emit('update','width',Number(v))"/><label>Relief radius <output>{{ values.reliefRadius.toFixed(1) }} mm</output></label><Slider :model-value="values.reliefRadius" :min="0.5" :max="4" :step="0.1" @update:model-value="v => emit('update','reliefRadius',Number(v))"/><label>Stop distance <output>{{ values.depthFromLip.toFixed(1) }} mm</output></label><Slider :model-value="values.depthFromLip" :min="0.5" :max="3" :step="0.1" @update:model-value="v => emit('update','depthFromLip',Number(v))"/></template></section></template>
